<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/cms/layout.php';$user=require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['operation']??'');$type=(string)($_POST['type']??'');$id=(int)($_POST['id']??0);$table=$type==='material'?'materials':($type==='member'?'members':'');if($table===''){redirect('/admin/trash.php');}
if($op==='restore'){db()->prepare("UPDATE $table SET deleted_at=NULL,deleted_by=NULL,updated_by=?,updated_at=? WHERE id=? AND deleted_at IS NOT NULL")->execute([$user['id'],now_utc(),$id]);audit($type.'_restore',$type,$id);flash('success','内容已恢复。');redirect('/admin/trash.php');}
if($op==='purge'){$user=require_super();$s=db()->prepare("SELECT * FROM $table WHERE id=? AND deleted_at IS NOT NULL");$s->execute([$id]);$row=$s->fetch();if($row){if($type==='material'){$path=cms_upload_root().'/materials/'.$row['storage_name'];if(is_file($path)){unlink($path);}}elseif(!empty($row['photo_path'])&&str_starts_with($row['photo_path'],'/uploads/members/')){$path=dirname(__DIR__).$row['photo_path'];if(is_file($path)){unlink($path);}}db()->prepare("DELETE FROM $table WHERE id=?")->execute([$id]);audit($type.'_purge',$type,$id);}flash('success','内容已永久删除。');redirect('/admin/trash.php');}}
$materials=db()->query('SELECT id,title_zh AS title,deleted_at FROM materials WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC')->fetchAll();$members=db()->query('SELECT id,name_zh AS title,deleted_at FROM members WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC')->fetchAll();$items=[];foreach($materials as $r){$r['type']='material';$items[]=$r;}foreach($members as $r){$r['type']='member';$items[]=$r;}usort($items,fn($a,$b)=>strcmp($b['deleted_at'],$a['deleted_at']));admin_header('回收站',$user);?><section class="panel"><div class="panel-head"><div><h2>已删除内容</h2><small>普通管理员可恢复；只有超级管理员可永久删除。</small></div></div><div class="table-wrap"><table><thead><tr><th>名称</th><th>类型</th><th>删除时间</th><th>操作</th></tr></thead><tbody><?php foreach($items as $row):?><tr><td><strong><?=e($row['title'])?></strong></td><td><?=$row['type']==='material'?'网站资料':'会员档案'?></td><td><?=e($row['deleted_at'])?></td><td><div class="actions"><form method="post"><?=csrf_input()?><input type="hidden" name="operation" value="restore"><input type="hidden" name="type" value="<?=e($row['type'])?>"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn small">恢复</button></form><?php if($user['role']===CMS_ROLE_SUPER):?><form method="post"><?=csrf_input()?><input type="hidden" name="operation" value="purge"><input type="hidden" name="type" value="<?=e($row['type'])?>"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn small danger" data-confirm="永久删除后无法恢复，确认继续？">永久删除</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td class="empty" colspan="4">回收站为空。</td></tr><?php endif;?></tbody></table></div></section><?php admin_footer();
